def _holes(holes): return '\n'.join(f"  translate([{h['x']}, {h['y']}, -0.1]) cylinder(h = height + 0.2, d = {h['diameter']}, $fn = 48);" for h in holes or [])
def generate_openscad(spec):
    p=spec.get('part')
    if not p: return {'supported':False,'code':'','message':'Only part specs are supported.'}
    a=p['parameters']
    if p['type']=='rounded_rectangular_plate': return {'supported':True,'code':f"// Generated by printspec 0.1.0\nlength = {a['length']};\nwidth = {a['width']};\nheight = {a['thickness']};\ncorner_radius = {a['cornerRadius']};\n\ndifference() {{\n  hull() {{\n    for (x = [-length/2 + corner_radius, length/2 - corner_radius])\n      for (y = [-width/2 + corner_radius, width/2 - corner_radius])\n        translate([x, y, 0]) cylinder(h = height, r = corner_radius, $fn = 32);\n  }}\n{_holes(a.get('holes'))}\n}}\n"}
    if p['type']=='spacer_block': return {'supported':True,'code':f"// Generated by printspec 0.1.0\nlength = {a['length']};\nwidth = {a['width']};\nheight = {a['height']};\n\ndifference() {{\n  translate([-length/2, -width/2, 0]) cube([length, width, height]);\n{_holes(a.get('holes'))}\n}}\n"}
    return {'supported':False,'code':'','message':f"Unsupported part family: {p['type']}"}
